-- Supabase schema skeleton for the air_quality brief
CREATE TABLE air_quality_raw (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  unit_id text NOT NULL,
  observed_at timestamptz NOT NULL,
  value double precision
);

CREATE MATERIALIZED VIEW air_quality_daily AS
SELECT unit_id, date_trunc('day', observed_at) AS day, avg(value) AS mean_value
FROM air_quality_raw GROUP BY 1, 2;

SELECT cron.schedule('refresh_air_quality', '0 */1 * * *',
  'REFRESH MATERIALIZED VIEW air_quality_daily');

